INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63161479', 63161479, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'KANTOR PUSAT DIREKTORAT JENDERAL PERKERETAAPIAN', 'Penataan Organisasi Direktorat Jenderal Perkeretaapian (Seleksi Tidak Mengikat)', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 498000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Maksud pelaksanaan kajian akademik ini adalah tercapainya peningkatan kinerja unit kerja di Direktorat Jenderal Perkeretaapian secara optimal dalam pelaksanaan urusan pemerintahan di bidang perkeretaapian. Tujuan pelaksanaan kajian akademik ini adalah tersedianya acuan bagi Direktorat Jenderal Perkeretaapian untuk melaksanakan penataan kembali organisasi dan tata kerja pada unit kerja di Direktorat Jenderal Perkeretaapian', 'Ruang lingkup kegiatan adalah: 1. Melakukan identifikasi dan inventarisasi dasar hukum mengenai penataan organisasi dan tata kerja di lingkungan Kementerian Perhubungan dan pelaksanaan urusan pemerintahan di bidang perkeretaapian; 2. Melakukan identifikasi permasalahan bagi unit kerja di Direktorat Jenderal Perkeretaapian untuk melaksanakan tugas pokok dan fungsi secara optimal; 3. Melakukan analisis kebutuhan pengembangan organisasi dan tata kerja pada unit kerja di Direktorat Jenderal Perkeretaapian; 4. Merumuskan rekomendasi sebagai tindak lanjut penataan kembali organisasi dan tata kerja pada unit kerja di Direktorat Jenderal Perkeretaapian; 5. Melakukan analisis Kriteria Klasifikasi Balai Teknik Perkeretaapian; 6. Identifikasi dan inventarisasi dasar hukum Pelayanan Publik pada Balai Teknik Perkeretaapian.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 693120);
