INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63160680', 63160680, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Belanja Tenaga Ahli - Tim Teknis Pengawas Pekerjaan pada Pekerjaan Pembuatan Peta dengan PUNA', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Timur, Sidoarjo (Kab.)', 18000000, 'March 2026', 'APBD', 1, 1, '1 Paket', 'Belanja Tenaga Ahli dan Tim Teknis Pengawas Pekerjaan Pembuatan Peta Menggunakan PUNA Uraian pekerjaan ini meliputi penyediaan tenaga ahli dan tim teknis pengawas yang bertugas melakukan pengawasan teknis, pengendalian mutu, serta evaluasi pelaksanaan pekerjaan pembuatan peta yang dilaksanakan dengan metode pemotretan udara menggunakan Pesawat Udara Nir Awak (PUNA). Tenaga ahli dan tim teknis pengawas bertanggung jawab memastikan bahwa seluruh tahapan pekerjaan pembuatan peta, mulai dari persiapan, pelaksanaan pemotretan udara, pengolahan data, hingga penyusunan produk akhir peta, dilaksanakan sesuai dengan ketentuan teknis, standar pemetaan, jadwal, dan spesifikasi yang telah ditetapkan oleh Pejabat Pembuat Komitmen (PPK). Ruang Lingkup Pekerjaan meliputi: Melakukan telaah dokumen perencanaan dan spesifikasi teknis pekerjaan pembuatan peta berbasis PUNA. Memberikan masukan teknis terkait metode pemotretan udara, perencanaan jalur terbang, dan pengaturan Ground Control Point (GCP). Melakukan pengawasan terhadap pelaksanaan pemotretan udara menggunakan PUNA agar sesuai dengan standar keselamatan dan ketentuan penerbangan. Mengawasi proses pengumpulan data spasial dan kualitas citra udara yang dihasilkan. Melakukan pengawasan dan evaluasi terhadap proses pengolahan data (ortofoto, DSM/DTM, mosaik citra, dan produk turunan lainnya). Memastikan ketelitian geometrik dan kualitas peta sesuai standar pemetaan yang berlaku. Melakukan verifikasi dan validasi hasil pekerjaan pemetaan, termasuk pengecekan akurasi dan kelengkapan atribut data. Memberikan rekomendasi perbaikan apabila ditemukan ketidaksesuaian teknis atau mutu hasil pekerjaan. Menyusun laporan hasil pengawasan secara berkala dan laporan akhir pengawasan. Mendampingi proses serah terima hasil pekerjaan pembuatan peta dari penyedia kepada pengguna. Dengan terlaksananya pekerjaan ini, diharapkan kualitas hasil pembuatan peta menggunakan PUNA dapat terjamin, memenuhi standar teknis, serta dapat dimanfaatkan secara optimal untuk mendukung kebutuhan perencanaan dan pengelolaan data spasial', 'Spesifikasi Pekerjaan 1. Nama Pekerjaan Belanja Tenaga Ahli dan Tim Teknis Pengawas Pekerjaan Pembuatan Peta Menggunakan PUNA 2. Jenis Pekerjaan Jasa Konsultansi Pengawasan Teknis 3. Maksud dan Tujuan Memberikan layanan pengawasan teknis dan pengendalian mutu terhadap pelaksanaan pekerjaan pembuatan peta berbasis pemotretan udara menggunakan PUNA agar hasil pekerjaan memenuhi standar teknis pemetaan, ketentuan keselamatan, serta spesifikasi yang telah ditetapkan. 4. Lingkup Pekerjaan Spesifikasi pekerjaan ini meliputi: Pengawasan tahap persiapan pekerjaan pemetaan berbasis PUNA. Pengawasan perencanaan terbang dan penempatan Ground Control Point (GCP). Pengawasan pelaksanaan pemotretan udara menggunakan PUNA. Pengawasan kualitas citra udara dan data hasil pemotretan. Pengawasan proses pengolahan data spasial (ortofoto, DSM/DTM, mosaik). Pemeriksaan ketelitian geometrik dan kualitas peta. Verifikasi dan validasi hasil pekerjaan pembuatan peta. Penyusunan rekomendasi teknis dan tindak lanjut perbaikan. Penyusunan laporan pengawasan berkala dan laporan akhir. Pendampingan proses serah terima hasil pekerjaan. 5. Standar dan Acuan Teknis Standar pemetaan nasional yang berlaku Pedoman teknis pemetaan berbasis PUNA Ketentuan keselamatan penerbangan PUNA Spesifikasi teknis pekerjaan pembuatan peta 6. Kualifikasi Personel Penyedia wajib menyediakan tenaga ahli dan tim teknis dengan kualifikasi sebagai berikut: Tenaga Ahli Pemetaan/GIS berpengalaman dalam pemetaan berbasis PUNA Tenaga Ahli Fotogrametri Tenaga Ahli Pengolahan Data Spasial Tim Teknis Pengawas Lapangan 7. Metodologi Pelaksanaan Telaah dokumen teknis dan perencanaan Pengawasan lapangan dan administrasi Evaluasi mutu hasil pekerjaan Pelaporan dan rekomendasi teknis 8. Waktu Pelaksanaan Jangka waktu pelaksanaan disesuaikan dengan durasi pekerjaan pembuatan peta Jadwal rinci ditetapkan dalam kontrak 9. Output Pekerjaan Laporan pengawasan berkala Laporan akhir pengawasan Berita acara hasil verifikasi dan validasi teknis 10. Koordinasi dan Pelaporan Koordinasi intensif dengan PPK dan penyedia pekerjaan pemetaan Penyampaian laporan secara tertulis dan tepat waktu 11. Pengendalian Mutu Pemeriksaan kesesuaian hasil pekerjaan terhadap spesifikasi Pemberian rekomendasi perbaikan teknis Dokumentasi hasil pengawasan 12. Serah Terima Pekerjaan Dilaksanakan setelah seluruh tugas pengawasan selesai Dituangkan dalam Berita Acara Serah Terima (BAST)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 695410);
