INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63162499', 63162499, 'analyze_legacy', 'Kab. Sidoarjo', 'kabkota', 'Badan Pelayanan Pajak Daerah', 'Pengadaan Jasa Pembuatan Peta Menggunakan PUNA', 'Jasa Lainnya', 'Seleksi', 'Jawa Timur, Sidoarjo (Kab.)', 944979000, 'February 2026', 'APBD', 1, 1, '21000 Hektar', 'Uraian pekerjaan ini meliputi penyediaan jasa pembuatan peta melalui metode pemotretan udara menggunakan Pesawat Udara Nir Awak (PUNA) untuk menghasilkan data spasial yang akurat, mutakhir, dan dapat dipertanggungjawabkan, guna mendukung perencanaan, pengelolaan, dan pengambilan kebijakan di lingkungan perangkat daerah. Pekerjaan pembuatan peta menggunakan PUNA dilaksanakan secara profesional dengan mengacu pada standar teknis pemetaan, ketentuan keselamatan penerbangan PUNA, serta spesifikasi yang ditetapkan oleh Pejabat Pembuat Komitmen (PPK). Ruang Lingkup Pekerjaan meliputi: Persiapan Pekerjaan, meliputi pengumpulan data awal, penentuan wilayah pemetaan, perencanaan jalur terbang, dan penyusunan rencana kerja. Perizinan dan Koordinasi, termasuk pengurusan perizinan penerbangan PUNA dan koordinasi dengan instansi terkait. Penempatan Ground Control Point (GCP) dan/atau Check Point (CP) untuk menjamin akurasi geometrik peta. Pelaksanaan Pemotretan Udara menggunakan PUNA sesuai rencana terbang dan standar keselamatan. Pengolahan Data Citra Udara, meliputi pembuatan ortofoto, mosaik citra, Digital Surface Model (DSM), dan/atau Digital Terrain Model (DTM). Penyusunan Peta, baik peta dasar maupun peta tematik sesuai kebutuhan pengguna. Pemeriksaan dan Pengendalian Mutu, termasuk uji ketelitian geometrik dan kualitas hasil peta. Penyempurnaan Hasil, apabila terdapat ketidaksesuaian atau koreksi berdasarkan hasil evaluasi. Penyusunan Laporan, meliputi laporan antara dan laporan akhir pekerjaan. Serah Terima Hasil Pekerjaan, yang dituangkan dalam Berita Acara Serah Terima (BAST). Dengan terlaksananya pekerjaan ini, diharapkan tersedia peta hasil pemotretan udara menggunakan PUNA yang akurat, mutakhir, dan dapat dimanfaatkan secara optimal untuk mendukung kegiatan pemetaan dan pengelolaan data spasial.', 'Pengadaan Jasa Pembuatan Peta Menggunakan PUNA 1. Nama Pekerjaan Pengadaan Jasa Pembuatan Peta Menggunakan Pesawat Udara Nir Awak (PUNA) 2. Jenis Pekerjaan Jasa Konsultansi Pemetaan dan Pengolahan Data Spasial 3. Maksud dan Tujuan Menyediakan jasa pembuatan peta berbasis pemotretan udara menggunakan PUNA untuk menghasilkan data spasial yang akurat, mutakhir, dan sesuai standar teknis pemetaan guna mendukung perencanaan, pengelolaan, dan pengambilan kebijakan. 4. Lingkup Pekerjaan Lingkup pekerjaan meliputi: Persiapan dan perencanaan pekerjaan pemetaan. Perencanaan jalur terbang dan ketinggian terbang PUNA. Penempatan dan pengukuran Ground Control Point (GCP) dan/atau Check Point (CP). Pelaksanaan pemotretan udara menggunakan PUNA. Pengolahan data citra udara. Penyusunan produk peta sesuai kebutuhan. Pengendalian dan pemeriksaan mutu hasil pekerjaan. Penyusunan laporan dan serah terima hasil pekerjaan. 5. Spesifikasi Teknis PUNA Jenis PUNA: fixed wing atau multirotor (sesuai kebutuhan wilayah) Kamera: resolusi tinggi, kalibrasi pabrikan Sistem navigasi: GNSS/IMU Ground Sampling Distance (GSD): disesuaikan kebutuhan (≤ 10 cm/pixel atau setara) Sistem keselamatan terbang sesuai regulasi yang berlaku 6. Spesifikasi Teknis Pelaksanaan Pelaksanaan pemotretan dilakukan pada kondisi cuaca yang mendukung Overlap memanjang dan menyamping sesuai standar fotogrametri Penempatan GCP/CP memenuhi ketentuan ketelitian geometrik Data disimpan dan diamankan selama proses pekerjaan 7. Spesifikasi Pengolahan Data Pembuatan ortofoto terkoreksi geometrik Pembuatan mosaik citra Pembuatan DSM/DTM (jika dipersyaratkan) Digitasi fitur peta (batas bidang, jalan, bangunan, sungai, dll.) Integrasi atribut data spasial 8. Spesifikasi Produk Peta (Output) Ortofoto resolusi tinggi Peta digital (format SHP/GeoJSON atau setara) Peta cetak (jika diperlukan) Database spasial Metadata peta Laporan teknis dan laporan akhir 9. Standar dan Acuan Teknis Standar pemetaan nasional yang berlaku Pedoman teknis pemetaan berbasis PUNA Ketentuan keselamatan penerbangan PUNA Spesifikasi teknis dalam KAK dan kontrak 10. Personel Pelaksana Team Leader / Ahli Pemetaan Operator PUNA bersertifikat Ahli Fotogrametri Ahli GIS/Pengolahan Data Spasial Surveyor GCP/CP 11. Jangka Waktu Pelaksanaan Jangka waktu pelaksanaan disesuaikan dengan luas wilayah dan kompleksitas pekerjaan Jadwal rinci dituangkan dalam kontrak 12. Pengendalian Mutu Pemeriksaan kualitas citra Uji ketelitian geometrik Validasi hasil peta bersama pengguna Perbaikan hasil apabila ditemukan ketidaksesuaian 13. Keselamatan dan Keamanan Mematuhi prosedur keselamatan penerbangan PUNA Menjaga keamanan personel dan peralatan Menjamin kerahasiaan data hasil pemetaan 14. Pelaporan Laporan pendahuluan Laporan kemajuan Laporan akhir pekerjaan 15. Serah Terima Pekerjaan Dilaksanakan setelah seluruh output terpenuhi Dibuktikan dengan Berita Acara Serah Terima (BAST)', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 695517);
