INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66284746', 66284746, 'analyze_legacy', 'Provinsi Jawa Timur', 'provinsi', 'DINAS KELAUTAN DAN PERIKANAN', 'Belanja Jasa Tenaga Pendukung Individual Instalasi Perikanan Budidaya Kepanjen I (Januari-Maret) Tahun Anggaran 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Timur, Malang (Kab.)', 12000000, 'January 2026', 'APBD', 1, 1, '3 OB', '10. Belanja Jasa Tenaga Pendukung Individual Instalasi Perikanan Budidaya Kepanjen I (Januari-Maret) Tahun Anggaran 2026 - Membantu penyusunan matrik operasional produksi di Instalasi Perikanan Budidaya Kepanjen - Membantu menentukan target pembenihan maupun pembesaran di Instalasi Perikanan Budidaya Kepanjen yang bertujuan untuk optimalisasi kegiatan budidaya - Membantu penyesuaian SPO pembenihan dan pembesaran di Instalasi Perikanan Budidaya Kepanjen - Membuat form pengecekan kualitas air - Membuat form monitoring hama dan penyakit - Membuat form monitoring pertumbuhan - Membantu analisis FR, HR, dan SR pembenihan masing masing komoditas di Instalasi Perikanan Budidaya Kepanjen - Menghitung kebutuhan pakan pembenihan dan pembesaran berdasarkan, DOC, ADG, ABW, untuk optimalisasi Budidaya - Membantu analisis Kelayakan dan Efektivitas produksi pembenihan maupun pembesaran di Instalasi Perikanan Budidaya Kepanjen - Menyusun analsis usaha pembenihan dan pembesaran di Instalasi Perikanan Budidaya Kepanjen yang bertujuan untuk produksi yang berkelanjutan - Melaksanakan tugas tambahan lain yang di berikan atasan', 'Sertifikasi Kompetensi : Teknologi Akuakultur Tenaga Pendukung Individual memiliki persyaratan sebagai berikut: ● Minimal tingkat Pendidikan sarjana (S-1) dari Perguruan Tinggi Negeri atau Swasta yang terakreditasi; ● Memiliki sertifikat keahlian dari Badan Nasional Sertifikasi Profesi dengan kompetensi bidang Administrasi Perkantoran dengan kualifikasi/kompetensi Pengelolaan Administrasi Kantor yang masih berlaku; ● Memiliki pengalaman bekerja sekurang-kurangnya 6 bulan di bidang nya.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 696023);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63162945', 63162945, 'analyze_legacy', 'Kementerian Pertahanan', 'central', 'LANTAMAL V SURABAYA TNI AL', 'Belanja Barang Persediaan Barang Konsumsi Urikkes Intensif III Termin II TA 2026', 'Barang', 'E-Purchasing', 'Jawa Timur, Surabaya (Kota)', 427056000, 'June 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, 'Satu Paket', 'Pembinaan kesehatan personel TNI Angkatan Laut pada dasarnya adalah merupakan upaya pemeliharaan dan peningkatan kesehatan personel TNI Angkatan Laut guna mewujudkan tuntutan kebutuhan penugasan personel TNI Angkatan Laut sesuai dengan spectrum penugasan dan peranannya sebagai kekuatan pertahanan penegakan hukum di laut. Salah satu upaya pemeliharaan dan peningkatan kesehatan prajurit adalah melalui pelaksanaan Urikkes Intensif IIIas secara berkala dan berkesinambungan, dengan demikian diharapkan setiap gejala penyakit dapat diketahui secara dini sehingga kondisi kesehatan personel TNI Angkatan Laut dapat dipelihara dan ditingkatkan', 'Penerima manfaat dari pelaksanaan pengadaan bekkes urikkes Intensif III adalah Diskes Kodaeral V sehingga dapat melaksanakan urikkes bagi personel TNI Angkatan Laut Kodaeral V dan UPT Mabesal Wilayah Surabaya dalam rangka pemenuhan personel yang berkualitas untuk melaksanakan tugas dan tanggung jawab sesuai dengan spektrum penugasannya', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 696024);
