INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66093954', 66093954, 'analyze_legacy', 'Kementerian Pertanian', 'central', 'DIREKTORAT JENDERAL LAHAN DAN IRIGASI PERTANIAN', 'ATK', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 6000000, 'March 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '( 12, BLN, @ 500000 )', '1. ATK ( 12, BLN, @ 500000 );', 'Pengadaan Alat Tulis Kantor (ATK) dialokasikan untuk mendukung kebutuhan administrasi dan operasional perkantoran selama 12 (dua belas) bulan, dengan satuan biaya sebesar Rp500.000 per bulan. ATK digunakan untuk menunjang kelancaran kegiatan surat-menyurat, penyusunan laporan, pengarsipan dokumen, serta kegiatan administrasi lainnya. Komponen ATK meliputi antara lain kertas, map, ordner, pulpen, pensil, tinta printer, toner, spidol, buku agenda, serta perlengkapan administrasi lainnya sesuai kebutuhan kantor. Pengadaan dilakukan secara bertahap sesuai kebutuhan riil setiap bulan dan harus memperhatikan prinsip efisiensi, efektivitas, serta didukung bukti pembelian yang sah sesuai ketentuan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 696061);
