INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62602917', 62602917, 'analyze_legacy', 'Kementerian Pendidikan Dasar dan Menengah', 'central', 'BGTK PROVINSI BALI', 'Paket Penginapan Fullboard Kegiatan Pengolahan data dan Kelulusan Peserta', 'Barang', 'Dikecualikan', 'Bali, Denpasar (Kota)', 37500000, 'June 2026', 'APBN', 1, 1, '1 Keg', 'Paket Penginapan Fullboard Kegiatan Pengolahan data dan Kelulusan Peserta', 'Paket Penginapan Fullboard Kegiatan Pengolahan data dan Kelulusan Peserta', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 696441);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62637433', 62637433, 'analyze_legacy', 'Kota Mojokerto', 'kabkota', 'DINAS KOMUNIKASI DAN INFORMATIKA', 'Belanja Jasa Tenaga Informasi dan Teknologi - Penyediaan Jasa Pelayanan Umum Kantor', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Mojokerto (Kota)', 385800000, 'January 2026', 'APBD', 1, 1, '1 paket', 'Belanja Jasa Tenaga Informasi dan Teknologi - Penyediaan Jasa Pelayanan Umum Kantor 1. Bagian Teknologi Informasi Telecenter Palapa DI/DII/DIII/S1 Terapan : 1 orang 2. Operator PPID dan Pengaduan DI/DII/DIII/S1 Terapan : 1 orang 3. Jasa Network Administrator Ijazah Min S1 Komputer : 1 orang 4. Programmer Pendidikan S1 dan pengalaman 2-5 thn : 2 orang 5. Jasa System Administrator Ijazah Min S1 Komputer Pengalaman 0-3 thn : 1 orang 6. Jasa Technical Support Network Ijazah Min SMA/SMK : 2 orang', 'Bagian teknologi informasi Telecenter Palapa mempunyai Tugas: 1. Sebagai Tenaga Kerja Bagian Teknologi Informasi Telecenter Palapa; 2. Sebagai Pengelola Telecenter Palapa Kota Mojokerto; 3. Mengkoordinasi dan menyiapkan segala keperluaan pelaksanaan kegiatan operasional Telecenter; 4. Menyediakan pelayanan akses informasi bagi masyarakat dan memfasilitasi pemberdayaan masyarakat dibidang Teknologi Informasi dan Komunikasi (TIK); 5. Menjamin keamanan dan pemeliharaan peralatan atau sarana dan prasarana Telecenter palapa serta memanfaatkanya secara berdayaguna untuk pemberdayaan masyarakat; 6. Menyusun dan melaksanakan rencana kerja Telecenter yang mengarah pada peningkatan kesejateraan masyarakat Kota Mojokerto; 7. Melakukan pendampingan kepada kolompok – kelompok masyarakat dalam memanfaatkan fasilitas Telecenter sebagai sumber informasi dalam upaya meningkatkan kesejahteraan; 8. Melaksanakan tugas kedinasan lain yang diperintahkan oleh Kepala Dinas, Sekretaris, Kepala Bidang ,Kepala Seksi, dan Kepala Sub Bagian pada Dinas Komunikasi dan Informatika Kota Mojokerto; 9. Melaporkan hasil kegiatan pada akhir bulan Operator PPID mempunyai tugas 1. Melaksanakan Pelayanan Permohonan Informasi Data dan proses penyimpanan, pendokumentasian, penyediaan dan pelayanan Informasi Publik lainnya 2. Menyiapkan dokumen untuk membantu PPID dalam melaksanakan pengujian konsekuensi atas Informasi Publik 3. Membuat, mengelola, memelihara, dan/atau memutakhirkan Daftar Informasi Publik 4. Menghimpun Informasi Publik dari seluruh unit kerja dan/atau satuan kerja 5. Membuat laporan layanan Informasi Publik 6. Melakukan ceklis kelengkapan Informasi Publik 7. Melaksanakan tugas kedinasan lain yang diperintahkan oleh kepala Dinas, Sekretaris, Kepala Bidang, Kepala seksi dan kepala sub bagian ( SIRUP, SIPD, Pengadaaan Barang Jasa DLL terkait Administrasi Perkantoran) Operator Pengaduan Layanan mempunyai tugas : 1. Melakukan Kegiatan Pelayanan Pengaduan, Aspirasi, Permohan Informasi dan Pengelolaan Layanan Teknis lainnya 2. Berkoordinasi dengan Pejabat Penghubung terkait Pengelolaan Pengaduan secara langsung atau tidak langsung. 3. Menjalankan fungsi sebagai admin instansi dan admin pejabat penghubung yang mengelola Pengaduan Pelayanan Publik melalui SP4N. 4. Menjadi petugas pelayanan pengaduan untuk membantu dalam proses penerimaa, pencatatan, verifikasi (berupa data maupun cek lokasi) dan distribusi Pengaduan. 5. Mendistribusikan Pengaduan kepada Pejabat Penghubung . 6. Memberikan tanggapan awal Pengaduan berdasarkan frequently asked question. 7. Melakukan Monitoring dan evaluasi tindak lanjut penyelesaian Pengaduan. 8. Membuat Laporan bulanan Pengaduan 9. Mengelola Sosial Media Pengaduan. 10. Menindaklanjuti Pengaduan dengan cermat, cepat, dan tuntas. 11. Memberikan Respon dan tanggapan sesuai substansi pengaduan. 12. Memberikan tanggapan ulang apabila diperlukan hingga penanganan pengaduan Tenaga Network Administrator mempunyai tugas : 1. Sebagai Tenaga Network Administrator pada Dinas Komunikasi dan Infromatika Kota Mojokerto dengan semua kompetensi yang melekat 2. Sebagai Tenaga Network Administrator yang bertanggungjawab dalam hal pengelolaan jaringan internet dan intranet yang dikelola oleh Dinas komunikasi dan Informatika Kota Mojokerto 3. Sebagai anggota dalam Tim Pelaksana Kegiatan Pengelolaan Jaringan Internet dan Intranet Pemerintah Kota Mojokerto 4. Melaksanakan tugas kedinasan lain yang diperintahkan oleh Kepala Dinas, Sekretaris, Kepala Bidang dan Kepala Subbagian pada Dinas Komunikasi dan Informatika Kota Mojokerto 5. Melaporkan hasil kegiatan pada akhir bulan kepada Pihak Pertama melalui Ketua Tim Pelaksana Swakelola Pekerjaan Pengelolaan Jaringan Internet dan intranet Pemerintah Kota Mojokerto Programmer mempunyai Tugas: 1. Melakukan pengkodean aplikasi pada pembangunan aplikasi SI PALAPA (Sistem Informasi Pelayanan Publik Kota Mojokerto Terpadu) meliputi layanan kelurahan, pembangunan api service, layanan pendidikan. 2. Melakukan pengkodean aplikasi pada pengembangan aplikasi dashboard eksekutif Pemerintah Kota Mojokerto. 3. Melakukan pengkodean aplikasi pada pembangunan aplikasi antrian pada Mall Pelayanan Publik GMSC. 4. Melakukan pengkodean aplikasi pada pengembangan aplikasi Survey Kepuasan Masyarakat yang terintegrasi dengan aplikasi antrian. 5. Melakukan pengkodean aplikasi pada pembangunan Rekrutmen Pegawai Non ASN 6. Melakukan pengkodean aplikasi pada pengembangan dan integrasi aplikasi sesuai kebutuhan OPD dan prioritas RPJMD Pemerintah Kota Mojokerto. 7. Melaksanakan tugas kedinasan lain yang diperintahkan oleh Kepala Dinas Komunikasi dan Informatika, Kepala Bidang Teknologi dan Informatika pada Dinas Komunikasi dan Informatika, Sub Koordinator Aplikasi dan Pengembangan Kota Cerdas pada Dinas Komunikasi dan Informatika Kota Mojokerto. 8. Melaporkan hasil kegiatan pada akhir bulan kepada PIHAK PERTAMA melalui Pejabat Pelaksana Teknis Kegiatan Pengembangan Aplikasi Dan Proses Bisnis Pemerintahan Berbasis Elektronik. Tenaga system administrator mempunyai Tugas : 1. Sebagai Tenaga System Administrator pada Dinas Komunikasi dan Infromatika Kota Mojokerto dengan semua kompetensi yang melekat 2. Sebagai Tenaga System Administrator yang bertanggungjawab dalam hal pengelolaan pusat data Pemerintah Kota Mojokerto yang dikelola oleh Dinas komunikasi dan Informatika Kota Mojokerto 3. Sebagai anggota dalam Tim Pelaksana Kegiatan Pengelolaan Pusat Data Pemerintah Kota Mojokerto 4. Melaksanakan tugas kedinasan lain yang diperintahkan oleh Kepala Dinas, Sekretaris, Kepala Bidang dan Kepala Subbagian pada Dinas Komunikasi dan Informatika Kota Mojokerto 5. Melaporkan hasil kegiatan pada akhir bulan kepada Pihak Pertama melalui Ketua Tim Pelaksana Swakelola Pekerjaan Pengelolaan Pusat Data Pemerintah Kota Mojokerto Tenaga Technical Support Network mempunyai tugas 1. Sebagai Technical Support Network pada Dinas Komunikasi dan Infromatika Kota Mojokerto dengan semua kompetensi yang melekat 2. Sebagai Technical Support Network yang bertanggungjawab dalam hal teknis seperti pemetaan, instalasi, pemindahan, pembongkaran, serta pelayanan gannguan untuk jaringan internet dan intranet yang dikelola oleh Dinas komunikasi dan Informatika Kota Mojokerto 3. Sebagai anggota dalam Tim Pelaksana Kegiatan Pengelolaan Pusat Data Pemerintah Kota Mojokerto 4. Melaksanakan tugas kedinasan lain yang diperintahkan oleh Kepala Dinas, Sekretaris, Kepala Bidang dan Kepala Subbagian pada Dinas Komunikasi dan Informatika Kota Mojokerto 5. Melaporkan hasil kegiatan pada akhir bulan kepada Pihak Pertama melalui Ketua Tim Pelaksana Swakelola Pekerjaan Pengelolaan Pusat Data Pemerintah Kota Mojokerto', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 696442);
