INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62637491', 62637491, 'analyze_legacy', 'Kota Mojokerto', 'kabkota', 'DINAS KOMUNIKASI DAN INFORMATIKA', 'Belanja Jasa Tenaga Administrasi - Penyediaan Jasa Pelayanan Umum Kantor', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Mojokerto (Kota)', 290400000, 'January 2026', 'APBD', 1, 1, '1 paket', 'Belanja Jasa Tenaga Administrasi - Penyediaan Jasa Pelayanan Umum Kantor 1. Tenaga Administrasi Umum Jasa Tenaga Kerja Non ASN : 2 orang 2. Tenaga Administrasi Umum Jasa Tenaga Kerja Non ASN Call Center 112 : 8 orang 3. Tenaga Administrasi Umum Jasa Tenaga Kerja Non ASN Sopir/Pengemudi : 1 orang', 'Tenaga Administrasi umum mempunyai tugas : 1. Menerima, mencatat, dan menyortir dokumen sesuai dengan prosedur dan ketentuan yang berlaku, agar memudahkan pencarian. 2. Mengelompokkan data masyarakat menurut jenis dan sifatnya, sesuai dengan prosedur dan ketentuan yang berlaku, agar memudahkan pendistribusian; 3. Mendokumentasikan dokumen sesuai dengan prosedur dan ketentuan yang berlaku, agar tertib administrasi; 4. Mengumpulkan bahan penyusunan program dan petunjuk pelaksanaan; 5. Membantu menyusun konsep rencana kegiatan ; 6. Membantu mengolah draft dokumen pengadaan, administrasi dan layanan lainnya; 7. Melaporkan hasil pelaksanaan tugas sesuai dengan prosedur yang berlaku sebagai bahan evaluasi dan pertanggungiawaban; 8. Melaksanakan tugas-tugas kedinasan lain yang diberikan oleh atasan baik secara langsung maupun tidak langsung. Call Taker 112 mempunyai Tugas : 1. Menerima laporan/permasalahan dari mayarakat 2. Melakukan penginputan dan verifikasi identitas pelapor:nama, nomer telepon, lokasi kejadian, dan titik lokasi kejadian 3. Menentukan kelayakan laporan untuk ditindaklanjuti 4. Menentukan jenis kegawadaruratan dan meneruskan laporan darurat ke OPD/instansi terkait 5. Pembuatan dan pengiriman laporan penyelesaian penanganan kejadian 6. Membagikan laporan tindaklanjut oleh OPD dimedia sosial(Instagram, Facebook, dan twitter) Pengemudi mempunyai tugas : 1. Memeriksa kelengkapan kendaraan dengan cara mengecek rem, oli dan lampu di mesin, air radiator, air aki dan tekanan udara ban agar kendaraan dapat dikendarai dengan baik; 2. Memanaskan mesin kendaraan guna mengetahui kelainan mesin; 3. Merawat kendaraan dengan cara membersihkan mesin, ruangan dalam dan luar kendaraan agar kendaraan kelihatan bersih; 4. Mengemudikan kendaraan berdasarkan tujuan dan ketentuan lalu lintas yang berlaku agar kendaraan dapat tiba di tujuan dengan selamat; 5. Memperbaiki kerusakan kecil agar kendaraan dapat beroperasional secara layak; 6. Melaporkan hasil pelaksanaan tugas sesuai dengan prosedur yang berlaku sebagai bahan evaluasi dan pertanggungiawaban; 7. Melaksanakan tugas kedinasan lain yang diperintahkan pimpinan baik tertulis maupun lisan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 696529);
