INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62606266', 62606266, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'BALAI PELATIHAN DAN PENGEMBANGAN TEKNOLOGI INFORMASI DAN KOMUNIKASI', 'Pengadaan Jasa Layanan Internet di Lingkungan BPPTIK Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Bekasi (Kab.)', 1455000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Pengadaan Jasa Layanan Internet di Lingkungan BPPTIK Tahun Anggaran 2026 merupakan pekerjaan penyediaan layanan konektivitas internet yang andal, stabil, dan aman untuk mendukung operasional, layanan administrasi, serta kegiatan pembelajaran dan pelatihan di lingkungan BPPTIK. Ruang lingkup pekerjaan meliputi penyediaan layanan internet utama (main link) dan cadangan (backup link) berbasis fiber optik dedicated, penyediaan alamat IP publik, perangkat jaringan pendukung, layanan pemantauan jaringan, serta layanan profesional berupa dukungan teknis dan pemeliharaan jaringan secara berkala dan responsif. Penyedia bertanggung jawab untuk menjamin kualitas layanan sesuai Service Level Agreement (SLA), memastikan ketersediaan layanan internet secara berkelanjutan, serta memberikan dukungan teknis 7x24 jam untuk meminimalkan gangguan dan waktu pemulihan layanan.', 'A. Layanan Internet: 1. Main Link Fiber Optik Dedicated (2000Mbps) 2. Backup Link Fiber Optik Dedicated (200Mbps) 3. IP Publik (/28) 4. Router Mikrotik 5. SLA (Service Level Agreemenet ) 99,9% 6. Network Monitoring (PRTG) B. Layanan Profesional Engineer On Site for Maintenance meliputi: 1. Pengecekan dan Pemeliharaan EiP (DHCP Server ) 2. Pengecekan dan Pemeliharaan Switch Core 3. Pemeliharaan Perangkat Router 4. Pembuatan Services VPN 5. Pembuatan Services Management Bandwidth 6. Pembuatan Services Blocking Site 7. Engineer On Site minimal 2x dalam 1 Bulan 8. KAT (Key Account Technical) 9. Technical Support - Layanan On-Call 7x24 10. MTTR (Mean Time To Response) - Jangka Waktu Kontrak Pelaksanaan pekerjaan dilaksanakan selama 12 (dua belas) bulan atau 1 (satu) tahun, terhitung sejak tanggal mulai kontrak (SPMK) sampai dengan berakhirnya masa kontrak. - Sistem Pembayaran Pembayaran dilakukan secara termin sesuai dengan ketentuan yang tercantum dalam kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 699097);
